src/auth.ts.source:
/**
 * OIDC bearer-token verification for protected endpoints (port of auth.py).
 *
 * SPA-direct bearer: the frontend sends `Authorization: Bearer <jwt>` and this
 * middleware verifies it against the provider's JWKS (RS256), then derives identity
 * from the claims. Secure by default: when authRequired is true, every request must
 * carry a valid, in-scope token; authRequired=false yields an anonymous principal.
 */
import type { RequestHandler, Request } from "express";
import {
  createRemoteJWKSet,
  jwtVerify,
  type JWTPayload,
  type JWTVerifyGetKey,
  type KeyLike,
} from "jose";
import type { Settings } from "./config.js";
import { HttpError } from "./errors.js";

export const REQUIRED_SCOPE = "execute:code";

export interface Principal {
  userId: string | null;
  tenantId: string | null;
}

// A key resolver is either a static key (tests) or a remote JWKS function (prod).
type KeyInput = JWTVerifyGetKey | KeyLike;

// One cached JWKS resolver per URL — mirrors the lru_cached PyJWKClient.
const jwksCache = new Map<string, JWTVerifyGetKey>();
function jwksFor(url: string): JWTVerifyGetKey {
  let set = jwksCache.get(url);
  if (!set) {
    set = createRemoteJWKSet(new URL(url));
    jwksCache.set(url, set);
  }
  return set;
}

function bearerToken(req: Request): string {
  const header = req.get("authorization") ?? "";
  const firstSpace = header.indexOf(" ");
  const scheme = firstSpace === -1 ? header : header.slice(0, firstSpace);
  const token = firstSpace === -1 ? "" : header.slice(firstSpace + 1).trim();
  if (scheme.toLowerCase() !== "bearer" || !token) {
    throw new HttpError(401, "Missing or malformed Authorization header");
  }
  return token;
}

function hasRequiredScope(claims: JWTPayload): boolean {
  const scope = claims.scope;
  if (typeof scope === "string" && scope.trim().split(/\s+/).includes(REQUIRED_SCOPE)) {
    return true;
  }
  const perms = (claims as { permissions?: unknown }).permissions;
  return Array.isArray(perms) && perms.includes(REQUIRED_SCOPE);
}

/**
 * Build the requirePrincipal middleware. `keyOverride` (a static public key) is used
 * by tests in place of the remote JWKS; production omits it and resolves via JWKS URL.
 */
export function makeRequirePrincipal(settings: Settings, keyOverride?: KeyInput): RequestHandler {
  return async (req, res, next) => {
    if (!settings.authRequired) {
      res.locals.principal = { userId: null, tenantId: null } satisfies Principal;
      next();
      return;
    }
    try {
      const token = bearerToken(req); // throws HttpError(401) if missing/malformed
      const key = keyOverride ?? jwksFor(settings.oidcJwksUrl);
      const { payload } = await jwtVerify(token, key as JWTVerifyGetKey, {
        issuer: settings.oidcIssuer,
        audience: settings.oidcAudience,
        algorithms: ["RS256"],
        // `sub` is required, not optional: OIDC mandates it, and every downstream control is
        // keyed on it. Without it a verified token yields userId null, which would drop the
        // caller into the shared anonymous quota bucket — letting one such caller exhaust the
        // allowance of every other, and defeating per-user isolation.
        requiredClaims: ["exp", "iss", "aud", "sub"],
      });
      if (!hasRequiredScope(payload)) {
        next(new HttpError(403, `Token is missing the required scope '${REQUIRED_SCOPE}'`));
        return;
      }
      res.locals.principal = {
        userId: payload.sub ?? null,
        tenantId: (payload as { org_id?: string }).org_id ?? null,
      } satisfies Principal;
      next();
    } catch (err) {
      // A missing-header HttpError is already a 401; any jose failure maps to 401 too.
      if (err instanceof HttpError) {
        next(err);
        return;
      }
      next(new HttpError(401, "Invalid authentication token"));
    }
  };
}

src/sandbox/cloudRunSandbox.ts.source:
/**
 * SandboxBackend backed by Cloud Run sandboxes.
 *
 * Cloud Run injects /usr/local/gcp/bin/sandbox into the container when the service is deployed
 * with --sandbox-launcher. `sandbox do` creates an ephemeral sandbox, runs one command in it, and
 * deletes it — the same shape as `docker run --rm`, which is why this slots into the existing
 * port with no change to callers.
 *
 * What this gets for free, and DockerBackend has to ask for: outbound network is denied by
 * default, the host filesystem is read-only, and the sandbox cannot read the service's
 * environment variables or reach the metadata server. That last one matters most here — the
 * runtime identity's access token lives on that metadata server.
 *
 * What it does NOT get, and the README must say so (spec D7/D13/D16/S4): per-execution memory,
 * CPU and PID caps; processes inside run with sudo; and the readable filesystem is the
 * APPLICATION image, so /app/dist and /app/node_modules are visible. The concurrency cap and the
 * wall-clock timeout below are what bound a runaway payload now.
 */
import { spawn } from "node:child_process";
import type { SandboxBackend, ExecutionLimits } from "./base.js";
import type { SandboxResult } from "../schemas.js";
import { log } from "../log.js";

// ABSOLUTE paths, not bare command names. A Cloud Run sandbox inherits none of the host
// container's environment — that is the same property that keeps secrets and the metadata server
// out of it — so PATH inside the sandbox is EMPTY and a bare `python3` resolves against nothing:
//
//   error finding executable "python3" in PATH []: no such file or directory
//
// The interpreter is present (the repo-root Dockerfile installs it); only the lookup was missing.
// Do not "tidy" these back to bare names — it fails only on the deployed service, and only when
// code actually runs, which is the most expensive place to find out.
const PYTHON = "/usr/bin/python3";

const LANG_RUNNERS: Record<string, string[]> = {
  python: [PYTHON, "-I", "-B", "-c"],
};

/** Renders a capped buffer plus however many characters were thrown away while capping. */
function rendered(kept: string, dropped: number): string {
  return dropped === 0 ? kept : `${kept}\n…[truncated, ${dropped} more chars]`;
}

export class CloudRunSandboxBackend implements SandboxBackend {
  constructor(readonly cliPath = "/usr/local/gcp/bin/sandbox") {}

  async execute(code: string, language: string, limits: ExecutionLimits): Promise<SandboxResult> {
    const runner = LANG_RUNNERS[language];
    if (!runner) {
      return {
        stdout: "",
        stderr: `Unsupported language: '${language}'`,
        exitCode: 2,
        durationMs: 0,
        timedOut: false,
      };
    }

    // --write gives the sandbox a tmpfs overlay to write into; the base filesystem stays
    // read-only. NO --allow-egress, ever: deny-by-default egress is the property that makes this
    // backend match `--network none`, and passing it once would silently undo the isolation the
    // README claims. The code travels as a single argv element with no shell involved, so there
    // is no quoting or injection surface.
    const args = ["do", "--write", "--", ...runner, code];

    const started = process.hrtime.bigint();
    return await new Promise<SandboxResult>((resolve) => {
      // detached: its own process group. `sandbox do` runs the interpreter as a GRANDCHILD, so
      // killing only the CLI leaves it alive holding the stdio pipes — and 'close' never fires
      // while a pipe is held. execute() would then not return until the payload finished on its
      // own: the timeout would bound nothing and ConcurrencyLimitedBackend would never release
      // the slot. Those two are the only controls left after D7, so this is load-bearing.
      const child = spawn(this.cliPath, args, {
        stdio: ["ignore", "pipe", "pipe"],
        detached: true,
      });
      let timedOut = false;
      let settled = false;

      // Bound what is RETAINED, not merely what is reported. Accumulating without limit and
      // truncating at the end lets hostile code stream gigabytes into THIS process before the
      // timeout fires — and D7 removes the per-execution memory cap, so nothing else stands
      // between a print-loop and the whole Cloud Run instance. The pipes are still drained, just
      // not stored: stopping the reads would block the child instead.
      const cap = limits.maxOutputChars;
      let stdout = "";
      let stderr = "";
      let stdoutDropped = 0;
      let stderrDropped = 0;

      child.stdout.on("data", (c: Buffer) => {
        const chunk = c.toString();
        const room = Math.max(0, cap - stdout.length);
        if (room > 0) stdout += chunk.slice(0, room);
        stdoutDropped += chunk.length - Math.min(room, chunk.length);
      });
      child.stderr.on("data", (c: Buffer) => {
        const chunk = c.toString();
        const room = Math.max(0, cap - stderr.length);
        if (room > 0) stderr += chunk.slice(0, room);
        stderrDropped += chunk.length - Math.min(room, chunk.length);
      });

      const finish = (exitCode: number): void => {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        resolve({
          stdout: rendered(stdout, stdoutDropped),
          stderr: rendered(stderr, stderrDropped),
          exitCode,
          durationMs: Number((process.hrtime.bigint() - started) / 1_000_000n),
          timedOut,
        });
      };

      const timer = setTimeout(() => {
        timedOut = true;
        // SIGKILL to the whole GROUP: the payload is untrusted and under no obligation to handle
        // a signal politely, and the interpreter is a grandchild.
        try {
          process.kill(-(child.pid as number), "SIGKILL");
        } catch {
          child.kill("SIGKILL"); // already gone
        }
      }, limits.timeoutSeconds * 1000);

      child.on("error", (err) => {
        // The CLI is missing or not executable — infrastructure, not a program failure. Reported
        // as a result rather than a rejection so the base contract holds, but logged at error
        // level: it means the service was deployed without --sandbox-launcher.
        log.error("sandbox CLI could not be spawned", { err, cli: this.cliPath });
        stderr = `${stderr}\nsandbox CLI unavailable at ${this.cliPath}`;
        finish(126);
      });

      // 'exit', not 'close': exit fires when the process ends, close waits for every pipe to
      // drain — including one a killed grandchild may still hold. Give the streams a bounded
      // moment to flush, the same shape as dockerBackend's Promise.race([streamEnded, delay]).
      child.on("exit", (code) => {
        // Disarm FIRST. The 200ms flush below is a window in which the deadline could otherwise
        // still fire, flip timedOut, and turn a run that finished successfully a few milliseconds
        // early into a reported timeout with exit 124.
        clearTimeout(timer);
        const exitCode = timedOut ? 124 : (code ?? 1);
        const flush = setTimeout(() => finish(exitCode), 200);
        flush.unref?.();
      });
    });
  }
}

src/sandbox/dockerBackend.ts.source:
/**
 * Docker-based sandbox backend (port of docker_backend.py). Each execution runs in a
 * throwaway, heavily-restricted container:
 *   - no network (NetworkMode "none")
 *   - capped memory (+ no swap), CPU, and PIDs
 *   - read-only root filesystem with small tmpfs at /sandbox (code file) and /tmp
 *   - all Linux capabilities dropped + no-new-privileges
 *   - non-root user (baked into the image; also enforced here)
 *   - wall-clock timeout enforced here (the container is killed if it overruns)
 *   - force-removed so nothing persists between runs (--rm semantics)
 *
 * The code is passed via stdin to a tiny shell runner so we never mount host paths or
 * rely on the container filesystem being writable beyond the tmpfs.
 */
import Docker from "dockerode";
import { PassThrough } from "node:stream";
import type { SandboxBackend, ExecutionLimits } from "./base.js";
import type { SandboxResult } from "../schemas.js";

const LANG_RUNNERS: Record<string, { filename: string; cmd: string[] }> = {
  python: { filename: "code.py", cmd: ["python", "-I", "-B", "/sandbox/code.py"] },
};
const WORKDIR = "/sandbox";

const delay = (ms: number) => new Promise((r) => setTimeout(r, ms));
const elapsedMs = (start: bigint) => Number((process.hrtime.bigint() - start) / 1_000_000n);

function truncate(text: string, limit: number): string {
  if (text.length <= limit) return text;
  return `${text.slice(0, limit)}\n…[truncated, ${text.length - limit} more chars]`;
}

export class DockerBackend implements SandboxBackend {
  private readonly docker: Docker;

  constructor(private readonly image: string) {
    this.docker = new Docker(); // defaults to /var/run/docker.sock
  }

  async execute(code: string, language: string, limits: ExecutionLimits): Promise<SandboxResult> {
    const runner = LANG_RUNNERS[language];
    if (!runner) {
      return {
        stdout: "",
        stderr: `Unsupported language: '${language}'`,
        exitCode: 2,
        durationMs: 0,
        timedOut: false,
      };
    }

    // The container writes the provided code to the tmpfs and executes it. A shell
    // heredoc avoids mounting any host path into the untrusted container.
    const bootstrap =
      `cat > ${WORKDIR}/${runner.filename} <<'__LLM_EOF__'\n` +
      `${code}\n` +
      `__LLM_EOF__\n` +
      `exec ${runner.cmd.join(" ")}`;

    const started = process.hrtime.bigint();
    let container: Docker.Container | undefined;
    let timedOut = false;

    try {
      container = await this.docker.createContainer({
        Image: this.image,
        Cmd: ["sh", "-c", bootstrap],
        Tty: false,
        WorkingDir: WORKDIR,
        User: "1000:1000",
        HostConfig: {
          NetworkMode: "none",
          Memory: limits.memoryMb * 1024 * 1024,
          MemorySwap: limits.memoryMb * 1024 * 1024, // == Memory disables swap
          NanoCpus: Math.round(limits.cpus * 1_000_000_000),
          PidsLimit: limits.pidsLimit,
          ReadonlyRootfs: true,
          Tmpfs: {
            [WORKDIR]: "rw,size=8m,mode=1777",
            "/tmp": "rw,size=16m,mode=1777",
          },
          CapDrop: ["ALL"],
          SecurityOpt: ["no-new-privileges"],
          // Note: AutoRemove intentionally NOT set — we force-remove in finally so we
          // can reliably read logs and enforce the timeout kill first (== Python --rm).
        },
      });

      // Attach BEFORE start so no early output is lost; demux into two buffers.
      const stdoutChunks: Buffer[] = [];
      const stderrChunks: Buffer[] = [];
      const outStream = new PassThrough();
      const errStream = new PassThrough();
      outStream.on("data", (c: Buffer) => stdoutChunks.push(c));
      errStream.on("data", (c: Buffer) => stderrChunks.push(c));
      const attach = await container.attach({ stream: true, stdout: true, stderr: true });
      this.docker.modem.demuxStream(attach, outStream, errStream);
      const streamEnded = new Promise<void>((resolve) => {
        attach.on("end", () => resolve());
        attach.on("close", () => resolve());
        attach.on("error", () => resolve());
      });

      await container.start();

      const waitPromise = container.wait();
      const timeoutMs = limits.timeoutSeconds * 1000;
      // Cancelable timer: clear it when wait wins so we don't leave a live ref'd
      // setTimeout per execution (they'd accumulate for the full timeout under load).
      let timeoutHandle: ReturnType<typeof setTimeout> | undefined;
      const timeoutPromise = new Promise<{ kind: "timeout" }>((resolve) => {
        timeoutHandle = setTimeout(() => resolve({ kind: "timeout" as const }), timeoutMs);
      });
      let outcome: { kind: "done"; code: number } | { kind: "timeout" };
      try {
        outcome = await Promise.race([
          waitPromise.then((r) => ({ kind: "done" as const, code: Number(r?.StatusCode ?? -1) })),
          timeoutPromise,
        ]);
      } finally {
        if (timeoutHandle) clearTimeout(timeoutHandle);
      }

      let exitCode: number;
      if (outcome.kind === "timeout") {
        timedOut = true;
        exitCode = 124;
        await container.kill().catch(() => {});
        await waitPromise.catch(() => {}); // let wait settle after the kill
      } else {
        exitCode = outcome.code;
      }

      // Bounded flush of the attach stream so buffered output lands.
      await Promise.race([streamEnded, delay(500)]);

      const durationMs = elapsedMs(started);
      const stdout = Buffer.concat(stdoutChunks).toString("utf8");
      let stderr = Buffer.concat(stderrChunks).toString("utf8");
      if (timedOut) {
        stderr = `${stderr}\n[sandbox] killed after ${limits.timeoutSeconds}s timeout`.trim();
      }

      return {
        stdout: truncate(stdout, limits.maxOutputChars),
        stderr: truncate(stderr, limits.maxOutputChars),
        exitCode,
        durationMs,
        timedOut,
      };
    } catch (err) {
      const e = err as { statusCode?: number; message?: string };
      if (e?.statusCode === 404) {
        return {
          stdout: "",
          stderr:
            `[sandbox] image '${this.image}' not found. Build it first: ` +
            `\`docker build -t ${this.image} backend/sandbox-image\`.`,
          exitCode: 1,
          durationMs: elapsedMs(started),
          timedOut: false,
        };
      }
      return {
        stdout: "",
        stderr: truncate(String(e?.message ?? err), limits.maxOutputChars),
        exitCode: 1,
        durationMs: elapsedMs(started),
        timedOut: false,
      };
    } finally {
      if (container) {
        await container.remove({ force: true }).catch(() => {}); // ensure --rm even on timeout
      }
    }
  }
}

src/limits/concurrency.ts.source:
/**
 * In-process cap on concurrent sandbox executions.
 *
 * In-process is the CORRECT semantics here, not a compromise (D8 — "the cap refuses
 * immediately, no queue, in-process state"): each backend instance
 * protects the host it runs on, so the count is naturally per-instance — unlike the per-user
 * quota, which is a global budget and therefore lives in Redis.
 *
 * No mutex: Node is single-threaded and tryAcquire() has no await between reading and
 * incrementing `active`, so the check-and-increment is atomic within a tick.
 */
export class ConcurrencyLimiter {
  private active = 0;

  constructor(private readonly max: number) {}

  /** Whether every slot is taken. The single definition of "full" — tryAcquire consults it. */
  get saturated(): boolean {
    return this.active >= this.max;
  }

  /**
   * Take a slot, or null when full. The returned function releases it and is idempotent — a
   * double release must not invent capacity, and a leaked slot wedges the service for the
   * lifetime of the process.
   */
  tryAcquire(): (() => void) | null {
    if (this.saturated) return null;
    this.active += 1;
    let released = false;
    return () => {
      if (released) return;
      released = true;
      this.active -= 1;
    };
  }
}

src/limits/memoryQuota.ts.source:
/**
 * In-memory QuotaStore: fixed windows held in a Map. Correct for a single process and used
 * by the unit suites as the oracle for the Redis implementation.
 *
 * NOT the production store — a per-process counter would give N instances N x the intended
 * limit and would reset on every restart, making redeploy a quota bypass (D1, S7).
 */
import type { QuotaStore, QuotaLimits, QuotaDecision } from "./quota.js";

interface Window {
  count: number;
  resetAtMs: number;
}

/**
 * Sweep expired entries once the map passes this size. Without it the map grows one entry per
 * distinct identity forever, which would break the equivalence the shared contract suite
 * claims: the Redis store proves bounded state via TTLs (S6), so the oracle must hold the same
 * property rather than merely appear to.
 */
const SWEEP_THRESHOLD = 1000;

export class MemoryQuotaStore implements QuotaStore {
  private readonly windows = new Map<string, Window>();

  /** Drop windows that have already reset. O(n), amortised by the threshold check. */
  private sweep(now: number): void {
    for (const [k, w] of this.windows) {
      if (now >= w.resetAtMs) this.windows.delete(k);
    }
  }

  /**
   * Seconds until `key` has room, or 0 if it has room now. **Pure** — it must never create or
   * roll a window. Redis only creates a key on an allowed INCR, so a check that materialised a
   * zero-count window here would start the clock early on a request the other window refused,
   * expiring early and granting capacity sooner than Redis does. The two stores would then
   * disagree exactly where the contract suite claims they agree.
   */
  private peek(key: string, limit: number, now: number): number {
    const w = this.windows.get(key);
    if (!w || now >= w.resetAtMs) return 0; // absent or rolled over ⇒ empty ⇒ room
    if (w.count < limit) return 0;
    return Math.max(1, Math.ceil((w.resetAtMs - now) / 1000));
  }

  /** Charge one request, creating or rolling the window as needed. */
  private charge(key: string, windowSeconds: number, now: number): void {
    let w = this.windows.get(key);
    if (!w || now >= w.resetAtMs) {
      w = { count: 0, resetAtMs: now + windowSeconds * 1000 };
      this.windows.set(key, w);
    }
    w.count += 1;
  }

  async consume(key: string, limits: QuotaLimits): Promise<QuotaDecision> {
    const now = Date.now();
    if (this.windows.size >= SWEEP_THRESHOLD) this.sweep(now);

    // Evaluate BOTH windows and refuse with the LONGEST wait: reporting the burst window's
    // shorter TTL while the sustained window is also full would guarantee an obedient client a
    // second 429. Checking before charging also means a refusal costs nothing.
    const wait = Math.max(
      this.peek(`${key}:b`, limits.burst, now),
      this.peek(`${key}:s`, limits.sustained, now),
    );
    if (wait > 0) return { allowed: false, retryAfterSeconds: wait };

    this.charge(`${key}:b`, limits.burstWindowSeconds, now);
    this.charge(`${key}:s`, limits.sustainedWindowSeconds, now);
    return { allowed: true };
  }

  async usage(key: string): Promise<{ burst: number; sustained: number }> {
    const now = Date.now();
    const read = (k: string): number => {
      const w = this.windows.get(k);
      return !w || now >= w.resetAtMs ? 0 : w.count;
    };
    return { burst: read(`${key}:b`), sustained: read(`${key}:s`) };
  }

  async close(): Promise<void> {}
}

src/limits/middleware.ts.source:
/**
 * Per-user quota enforcement for /api/execute. Mounted AFTER requirePrincipal (so the
 * identity is the verified sub, never a header) and BEFORE llm.generate, which is what makes
 * a refusal cost zero Anthropic spend (S3).
 *
 * Note it also runs before the route's Zod validation, so a well-formed-JSON-but-invalid body
 * still consumes quota. That is deliberate — do not "fix" it by moving validation earlier.
 *
 * It does NOT cover malformed JSON: express.json() is mounted app-wide ahead of this, so a
 * syntactically broken body 422s before requirePrincipal or this middleware ever run. Those
 * requests are unmetered. They cost nothing downstream (no identity, no LLM, no sandbox), so
 * that is acceptable — but the invariant is narrower than "every rejected request is charged".
 */
import type { RequestHandler } from "express";
import type { Principal } from "../auth.js";
import { log } from "../log.js";
import type { QuotaStore, QuotaLimits } from "./quota.js";
import { quotaKey } from "./quota.js";
import { HttpError } from "../errors.js";

export function makeQuotaMiddleware(store: QuotaStore, limits: QuotaLimits): RequestHandler {
  return (_req, res, next) => {
    const principal = (res.locals.principal ?? { userId: null }) as Principal;
    void (async () => {
      let decision;
      try {
        decision = await store.consume(quotaKey(principal.userId), limits);
      } catch (err) {
        // FAIL OPEN (D5). The in-process sandbox concurrency cap still bounds the host, so an
        // outage degrades protection rather than removing it — the exposure narrows to
        // Anthropic spend for its duration. That is precisely why this logs at error level:
        // S9 treats silence here as a defect, because this line is the only thing standing
        // between a Redis outage and an unbounded bill.
        log.error("quota store unavailable — FAILING OPEN, requests are unmetered", { err });
        next();
        return;
      }
      if (decision.allowed) {
        next();
        return;
      }
      next(
        new HttpError(
          429,
          "Rate limit exceeded. Please wait before sending another request.",
          decision.retryAfterSeconds,
        ),
      );
    })();
  };
}

src/limits/quota.ts.source:
/**
 * Per-user request quota seam. Same shape as the HistoryStore seam: one interface, an
 * in-memory implementation used by unit tests, and a real one used in production, with a
 * single shared contract suite proving they behave identically.
 *
 * **Codes used across this package:** `D<n>` are decisions, recorded in
 * `docs/adr/0003-rate-limiting-approach.md`; `S<n>` are success criteria, in
 * `docs/specs/2026-08-08-per-user-rate-limiting.md`. They are cited rather than restated so the
 * rationale has exactly one home.
 *
 * Counting requests (not tokens) is deliberate — D3, "count requests in two windows". Refusals are decided
 * BEFORE llm.generate so a refused request costs nothing (S3).
 */

export interface QuotaLimits {
  burst: number;
  burstWindowSeconds: number;
  sustained: number;
  sustainedWindowSeconds: number;
}

export type QuotaDecision = { allowed: true } | { allowed: false; retryAfterSeconds: number };

export interface QuotaStore {
  /**
   * Charge one request against `key`. Returns allowed:false WITHOUT consuming quota when
   * either window is already at its limit, so a client in a retry loop cannot burn its own
   * sustained allowance while being refused.
   */
  consume(key: string, limits: QuotaLimits): Promise<QuotaDecision>;
  /** Current counts — for tests and diagnostics only. */
  usage(key: string): Promise<{ burst: number; sustained: number }>;
  /** Release resources (connections). No-op for the in-memory store. */
  close(): Promise<void>;
}

/**
 * Bucket key for a principal. Anonymous callers share ONE bucket (D2): with
 * AUTH_REQUIRED=false there is no sub to key on, and keying on IP would mean trusting
 * X-Forwarded-For — a spoofable header, and therefore a limiter bypass. A single shared
 * anonymous bucket is effectively a global rate limit, which is the right posture for a
 * mode that only exists for local development.
 */
export function quotaKey(userId: string | null): string {
  return userId === null ? "quota:anon" : `quota:user:${userId}`;
}

src/sandbox/concurrencyLimited.ts.source:
/**
 * SandboxBackend decorator enforcing the concurrency cap. A decorator rather than a change
 * inside DockerBackend so the future CloudRunBackend inherits the cap unchanged and
 * DockerBackend keeps one responsibility.
 *
 * Rejecting is within the base contract: that contract forbids rejecting on ordinary program
 * failure (non-zero exit, stderr, timeout), which this is not — it is a refusal to start at
 * all.
 *
 * Enforcement happens here and nowhere else (D9 — "the cap is enforced only at the sandbox
 * launch, never before the LLM call"). A cheaper check before llm.generate would
 * save the API call, but it would also refuse no-code prompts that never touch Docker.
 */
import type { SandboxBackend, ExecutionLimits } from "./base.js";
import type { SandboxResult } from "../schemas.js";
import type { ConcurrencyLimiter } from "../limits/concurrency.js";
import { HttpError } from "../errors.js";

export class ConcurrencyLimitedBackend implements SandboxBackend {
  /**
   * @param retryAfterSeconds hinted to a caller refused at the cap. Must be at least the
   * sandbox timeout: a slot is only guaranteed to free once the longest-running execution is
   * killed, so a shorter hint marches clients straight into a second 503 and amplifies load on
   * an already-saturated service. Pass `settings.sandboxTimeoutSeconds`.
   */
  constructor(
    private readonly inner: SandboxBackend,
    private readonly limiter: ConcurrencyLimiter,
    private readonly retryAfterSeconds: number,
  ) {}

  async execute(code: string, language: string, limits: ExecutionLimits): Promise<SandboxResult> {
    const release = this.limiter.tryAcquire();
    if (release === null) {
      // 503, not 429: the quota already passed, so this caller is inside its own allowance
      // and is being refused because of OTHER users' load. 429 would blame the wrong party.
      throw new HttpError(
        503,
        "The service is at capacity. Please retry in a few seconds.",
        this.retryAfterSeconds,
      );
    }
    try {
      return await this.inner.execute(code, language, limits);
    } finally {
      release();
    }
  }
}

