import { describe, it, expect, beforeAll } from "vitest";
import request from "supertest";
import {
  AUDIENCE,
  ISSUER,
  authSettings,
  makeKeypair,
  makeProtectedApp,
  makeToken,
  type Keypair,
} from "./helpers/auth.js";
import {
  MUTANTS,
  audienceNotChecked,
  authDisabled,
  expiryNotChecked,
  substringScope,
} from "./mutants.js";

let kp: Keypair;
beforeAll(async () => {
  kp = await makeKeypair();
});
const bearer = (t: string) => ({ Authorization: `Bearer ${t}` });
const ctx = () => ({ publicKey: kp.publicKey, issuer: ISSUER, audience: AUDIENCE });
const app = () => makeProtectedApp(authSettings(), kp.publicKey);

describe("mutation coverage: mutant accepts, real gate rejects", () => {
  it("expiry hole caught", async () => {
    const expired = await makeToken(kp.privateKey, { exp: Math.floor(Date.now() / 1000) - 10 });
    expect(await expiryNotChecked(expired, ctx())).toBe(200);
    expect((await request(app()).get("/protected").set(bearer(expired))).status).toBe(401);
  });

  it("substring-scope hole caught", async () => {
    const t = await makeToken(kp.privateKey, { scope: "openid execute:codex", permissions: [] });
    expect(await substringScope(t, ctx())).toBe(200);
    expect((await request(app()).get("/protected").set(bearer(t))).status).toBe(403);
  });

  it("audience hole caught", async () => {
    const t = await makeToken(kp.privateKey, { aud: "https://wrong" });
    expect(await audienceNotChecked(t, ctx())).toBe(200);
    expect((await request(app()).get("/protected").set(bearer(t))).status).toBe(401);
  });

  it("auth-disabled hole caught", async () => {
    expect(await authDisabled(null, ctx())).toBe(200);
    expect((await request(app()).get("/protected")).status).toBe(401);
  });

  it("every mutant still accepts a normal valid token", async () => {
    const t = await makeToken(kp.privateKey);
    for (const mutant of Object.values(MUTANTS)) {
      expect(await mutant(t, ctx())).toBe(200);
    }
  });
});

tests/limits/concurrency.test.ts.source:
import { describe, it, expect } from "vitest";
import request from "supertest";
import { ConcurrencyLimiter } from "../../src/limits/concurrency.js";
import { ConcurrencyLimitedBackend } from "../../src/sandbox/concurrencyLimited.js";
import { createApp } from "../../src/server.js";
import { loadSettings } from "../../src/config.js";
import { MemoryQuotaStore } from "../../src/limits/memoryQuota.js";
import { fakePrincipal } from "../helpers/auth.js";
import type { SandboxBackend } from "../../src/sandbox/base.js";

/** A backend that blocks until released, so concurrency is observable. */
function blockingBackend() {
  let active = 0;
  let peak = 0;
  const releases: (() => void)[] = [];
  const backend: SandboxBackend = {
    execute: async () => {
      active++;
      peak = Math.max(peak, active);
      await new Promise<void>((resolve) => releases.push(resolve));
      active--;
      return { stdout: "ok", stderr: "", exitCode: 0, durationMs: 1, timedOut: false };
    },
  };
  return { backend, releaseAll: () => releases.splice(0).forEach((r) => r()), peak: () => peak };
}

describe("ConcurrencyLimiter", () => {
  it("hands out at most `max` slots", () => {
    const limiter = new ConcurrencyLimiter(2);
    const a = limiter.tryAcquire();
    const b = limiter.tryAcquire();
    expect(a).not.toBeNull();
    expect(b).not.toBeNull();
    expect(limiter.tryAcquire()).toBeNull();
    expect(limiter.saturated).toBe(true);
    a!();
    expect(limiter.saturated).toBe(false);
    expect(limiter.tryAcquire()).not.toBeNull();
  });

  it("ignores a double release, so one caller cannot inflate capacity", () => {
    const limiter = new ConcurrencyLimiter(1);
    const release = limiter.tryAcquire()!;
    release();
    release();
    expect(limiter.tryAcquire()).not.toBeNull();
    expect(limiter.tryAcquire()).toBeNull(); // still 1, not 2
  });

  it("releases the slot when the inner backend throws", async () => {
    const limiter = new ConcurrencyLimiter(1);
    const throwing: SandboxBackend = {
      execute: async () => {
        throw new Error("boom");
      },
    };
    const wrapped = new ConcurrencyLimitedBackend(throwing, limiter, 10);
    await expect(wrapped.execute("x", "python", {} as never)).rejects.toThrow("boom");
    expect(limiter.saturated).toBe(false); // a leak here would wedge the service permanently
  });

  it("refuses with 503 rather than launching beyond the cap (S5)", async () => {
    const limiter = new ConcurrencyLimiter(1);
    const throwing: SandboxBackend = {
      execute: async () => {
        throw new Error("unreached");
      },
    };
    const wrapped = new ConcurrencyLimitedBackend(throwing, limiter, 10);
    limiter.tryAcquire(); // occupy the only slot
    await expect(wrapped.execute("x", "python", {} as never)).rejects.toMatchObject({
      status: 503,
    });
  });
});

describe("/api/execute under saturation", () => {
  it("never exceeds the cap and refuses the excess with 503 (S5)", async () => {
    const { backend, releaseAll, peak } = blockingBackend();
    const limiter = new ConcurrencyLimiter(2);
    const app = createApp({
      settings: loadSettings({
        AUTH_REQUIRED: "false",
        ANTHROPIC_API_KEY: "t",
        RATE_LIMIT_BURST: "100",
      }),
      llm: {
        generate: async () => ({
          shouldExecute: true,
          language: "python",
          code: "print(1)",
          message: null,
        }),
      } as never,
      sandbox: new ConcurrencyLimitedBackend(backend, limiter, 10),
      quota: new MemoryQuotaStore(),
      requirePrincipal: fakePrincipal("user-a"),
    });

    // CRITICAL: supertest requests are LAZY. `request(app).post(...).send(...)` builds a
    // thenable and dispatches nothing until .then() is called. Without the .then() below, no
    // request reaches the app before releaseAll() fires on an empty array, and the test hangs
    // until the suite times out rather than failing an assertion.
    const inflight = [0, 1, 2, 3, 4].map(() =>
      request(app)
        .post("/api/execute")
        .send({ prompt: "go" })
        .then((r) => r),
    );
    // Barrier, not a sleep. A fixed delay does not establish that all five requests reached the
    // limiter: on a slow runner releaseAll() could free a winner before a late request arrives,
    // that request would then acquire the freed slot, enter blockingBackend, and wait forever —
    // the test hangs instead of failing. Waiting until three refusals have actually been
    // observed proves the losers are done before anything is released.
    const refusals: number[] = [];
    inflight.forEach((p) => void p.then((r) => r.status === 503 && refusals.push(r.status)));
    const deadline = Date.now() + 5000;
    while (refusals.length < 3 && Date.now() < deadline) {
      await new Promise((r) => setTimeout(r, 5));
    }
    expect(refusals).toHaveLength(3); // fail loudly here rather than hanging below
    releaseAll();
    const responses = await Promise.all(inflight);

    // Exact counts, not `toBeLessThanOrEqual` — a cap of 2 that only ever ran 1 request would
    // satisfy an inequality while proving nothing.
    expect(peak()).toBe(2);
    expect(responses.filter((r) => r.status === 200)).toHaveLength(2);
    const refused = responses.filter((r) => r.status === 503);
    expect(refused).toHaveLength(3);
    for (const r of refused) {
      expect(Number(r.headers["retry-after"])).toBeGreaterThan(0);
    }
  });
});

