import { describe, it, expect, vi } from "vitest";
import request from "supertest";
import { createApp } from "../../src/server.js";
import { loadSettings } from "../../src/config.js";
import { MemoryQuotaStore } from "../../src/limits/memoryQuota.js";
import type { QuotaStore } from "../../src/limits/quota.js";
import { fakePrincipal } from "../helpers/auth.js";

const settings = () =>
  loadSettings({ AUTH_REQUIRED: "false", ANTHROPIC_API_KEY: "test", RATE_LIMIT_BURST: "2" });

const noCodeLlm = {
  generate: async () => ({
    shouldExecute: false,
    message: "nope",
    language: null,
    code: null,
  }),
};

function app(quota: QuotaStore, userId: string | null = "user-a") {
  return createApp({
    settings: settings(),
    llm: noCodeLlm as never,
    quota,
    requirePrincipal: fakePrincipal(userId),
  });
}

describe("quota middleware", () => {
  it("returns 429 with Retry-After once the quota is exhausted (S1)", async () => {
    const store = new MemoryQuotaStore();
    const a = app(store);
    await request(a).post("/api/execute").send({ prompt: "1" }).expect(200);
    await request(a).post("/api/execute").send({ prompt: "2" }).expect(200);
    const resp = await request(a).post("/api/execute").send({ prompt: "3" });
    expect(resp.status).toBe(429);
    expect(Number(resp.headers["retry-after"])).toBeGreaterThan(0);
  });

  it("never calls the LLM for a refused request (S3)", async () => {
    const store = new MemoryQuotaStore();
    const generate = vi.fn(noCodeLlm.generate);
    const a = createApp({
      settings: settings(),
      llm: { generate } as never,
      quota: store,
      requirePrincipal: fakePrincipal("user-a"),
    });
    await request(a).post("/api/execute").send({ prompt: "1" });
    await request(a).post("/api/execute").send({ prompt: "2" });
    await request(a).post("/api/execute").send({ prompt: "3" }).expect(429);
    expect(generate).toHaveBeenCalledTimes(2); // not 3 — the refusal cost nothing
  });

  it("throttling one user does not affect another (S2)", async () => {
    const store = new MemoryQuotaStore();
    for (const p of ["1", "2", "3"]) {
      await request(app(store, "user-a")).post("/api/execute").send({ prompt: p });
    }
    await request(app(store, "user-a")).post("/api/execute").send({ prompt: "x" }).expect(429);
    await request(app(store, "user-b")).post("/api/execute").send({ prompt: "x" }).expect(200);
  });

  it("charges the no-code path too (S4)", async () => {
    const store = new MemoryQuotaStore();
    await request(app(store)).post("/api/execute").send({ prompt: "tell me a joke" }).expect(200);
    expect((await store.usage("quota:user:user-a")).burst).toBe(1);
  });

  it("fails OPEN when the store throws, and says so loudly (D5, S9)", async () => {
    const broken: QuotaStore = {
      consume: async () => {
        throw new Error("ECONNREFUSED");
      },
      usage: async () => ({ burst: 0, sustained: 0 }),
      close: async () => {},
    };
    // The alarm now goes through log.ts, whose sink is console.log — severity is a field, not a
    // stream. Left on console.error, this spy would pass vacuously and stop guarding S9 at all.
    const spy = vi.spyOn(console, "log").mockImplementation(() => {});
    await request(app(broken)).post("/api/execute").send({ prompt: "1" }).expect(200);
    expect(spy).toHaveBeenCalled(); // silence would violate S9
    // Joined, not calls[0]: every severity shares this stream now, so any log line added
    // elsewhere in the request path would otherwise break this assertion in an unrelated PR.
    expect(spy.mock.calls.flat().join("\n")).toContain("FAILING OPEN");
    spy.mockRestore();
  });

  it("shares one bucket across anonymous callers (D2)", async () => {
    const store = new MemoryQuotaStore();
    await request(app(store, null)).post("/api/execute").send({ prompt: "1" }).expect(200);
    await request(app(store, null)).post("/api/execute").send({ prompt: "2" }).expect(200);
    await request(app(store, null)).post("/api/execute").send({ prompt: "3" }).expect(429);
  });
});

tests/sandbox/backendSelection.test.ts.source:
/**
 * The wiring test the unit tests cannot give you.
 *
 * config.test.ts proves the VALUE parses; cloudRunSandbox.test.ts proves the CLASS behaves.
 * Neither notices if server.ts stops consulting settings.sandboxBackend — every existing test
 * would stay green while production silently ran DockerBackend on a host with no Docker socket.
 *
 * This drives createApp() end to end and observes which backend answered, using the one signal
 * that distinguishes them without a live sandbox: CloudRunSandboxBackend reports a missing CLI as
 * exit 126 with "sandbox CLI unavailable", and DockerBackend never produces that string.
 */
import { describe, it, expect } from "vitest";
import request from "supertest";
import { createApp } from "../../src/server.js";
import { loadSettings } from "../../src/config.js";
import type { LLMService } from "../../src/llm.js";

// One structured call that both judges and generates — the shape main.test.ts fakes.
const fakeLlm = {
  generate: async () => ({
    shouldExecute: true,
    language: "python",
    code: "print('hi')",
    message: null,
  }),
} as unknown as LLMService;

describe("sandbox backend selection through createApp", () => {
  it("routes execution to the Cloud Run backend when SANDBOX_BACKEND=cloudrun", async () => {
    const settings = loadSettings({
      SANDBOX_BACKEND: "cloudrun",
      AUTH_REQUIRED: "false",
      ANTHROPIC_API_KEY: "test",
    });

    const res = await request(createApp({ settings, llm: fakeLlm }))
      .post("/api/execute")
      .send({ prompt: "anything" });

    // The CLI does not exist off Cloud Run, and that is the point: only CloudRunSandboxBackend
    // fails this way. Reaching it at all proves server.ts honoured the setting.
    expect(res.status).toBe(200);
    expect(res.body.exit_code).toBe(126);
    expect(res.body.stderr).toContain("sandbox CLI unavailable");
  });
});

tests/sandbox/dockerBackend.test.ts.source:
/**
 * The "image not found" path is the one place the backend tells a human what to run. With
 * per-slot tags (llm-sandbox:slot1, …) a hardcoded `llm-sandbox:latest` in that sentence sends
 * them to build an image the backend will never look for — and the symptom, an execution that
 * keeps failing after you "built the image", gives no hint why.
 */
import { describe, it, expect, vi, beforeEach } from "vitest";

const createContainer = vi.fn();

vi.mock("dockerode", () => ({
  default: class {
    createContainer = createContainer;
    modem = { demuxStream: vi.fn() };
  },
}));

const { DockerBackend } = await import("../../src/sandbox/dockerBackend.js");

describe("DockerBackend: image not found", () => {
  beforeEach(() => {
    createContainer.mockReset();
    createContainer.mockRejectedValue(
      Object.assign(new Error("no such image"), { statusCode: 404 }),
    );
  });

  const limits = {
    timeoutSeconds: 5,
    memoryMb: 256,
    cpus: 0.5,
    pidsLimit: 64,
    maxOutputChars: 20000,
  };

  it("names the image it actually looked for, in both halves of the message", async () => {
    const result = await new DockerBackend("llm-sandbox:slot2").execute(
      "print(1)",
      "python",
      limits,
    );
    expect(result.exitCode).toBe(1);
    expect(result.stderr).toContain("image 'llm-sandbox:slot2' not found");
    // The remediation must build the SAME tag, not a hardcoded one.
    expect(result.stderr).toContain("docker build -t llm-sandbox:slot2 backend/sandbox-image");
    expect(result.stderr).not.toContain("llm-sandbox:latest");
  });
});

